def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']
    # Decay old reputation, weight recent action more heavily
    decay = 0.9
    recent_weight = min(1.0, round_num / 5.0)
    if action == 'cooperate':
        new_reputation = current_reputation * decay + (1.0 * (1 - decay)) * recent_weight
    else:
        new_reputation = current_reputation * decay + (0.0 * (1 - decay)) * recent_weight
    return max(0.0, min(1.0, new_reputation))

def decide(recipient_reputation, round_num, my_history):
    # Early rounds: explore with cooperation
    if round_num <= 3:
        return True
    # Later rounds: cooperate if recipient reputation is above threshold
    threshold = 0.4
    return recipient_reputation >= threshold
